<template>
	<div class="xieyi-page">
		<div class="xieyi-form">
			<div class="tabs">
				<button
					v-for="tab in tabs"
					:key="tab.key"
					type="button"
					:class="{ active: activeTab === tab.key }"
					@click="activeTab = tab.key"
				>
					{{ tab.label }}
				</button>
			</div>

			<div v-if="activeTab === 'protocols'">
				<div v-if="messageType === 'error'" class="xieyi-actions">
					<span class="xieyi-message" :class="{ error: messageType === 'error' }">{{ message }}</span>
				</div>

				<section v-for="protocol in protocols" :key="protocol.operation" class="protocol-section">
					<div class="field-row">
						<label>接口名称</label>
						<div>{{ protocol.name }}</div>
					</div>
					<div class="field-row">
						<label>调用方法</label>
						<div>{{ protocol.operation }}</div>
					</div>
					<div class="field-row">
						<label>说明</label>
						<div>{{ protocol.description }}</div>
					</div>
					<div class="field-row">
						<label>返回值</label>
						<div>{{ protocol.returnType }}</div>
					</div>

					<div class="table-title">参数</div>
					<table>
						<thead>
							<tr>
								<th>参数</th>
								<th>说明</th>
								<th>备注</th>
							</tr>
						</thead>
						<tbody>
							<tr v-for="param in protocol.params" :key="param.name">
								<td>{{ param.name }}</td>
								<td>{{ param.description }}</td>
								<td>{{ param.remark }}</td>
							</tr>
						</tbody>
					</table>

					<div class="table-title">字段</div>
					<table>
						<thead>
							<tr>
								<th>序号</th>
								<th>名称</th>
								<th>说明</th>
								<th>单位</th>
							</tr>
						</thead>
						<tbody>
							<tr v-for="field in protocol.fields" :key="`${protocol.operation}-${field.index}`">
								<td>{{ field.index }}</td>
								<td>{{ field.name }}</td>
								<td>{{ field.comment || '-' }}</td>
								<td>{{ field.unit || '-' }}</td>
							</tr>
						</tbody>
					</table>
				</section>
			</div>

			<CallPanel
				v-if="activeTab === 'callData'"
				title="盾构数据 getData"
				:show-flag="true"
				:form="tbmDataForm"
				:loading="tbmDataCalling"
				:message="tbmDataMessage"
				:message-type="tbmDataMessageType"
				:result="tbmDataResult"
				@update-field="updateTBMDataForm"
				@submit="callTBMData"
			/>

			<CallPanel
				v-if="activeTab === 'callGuidance'"
				title="导向数据 getTBM"
				:show-flag="false"
				:form="tbmGuidanceForm"
				:loading="tbmGuidanceCalling"
				:message="tbmGuidanceMessage"
				:message-type="tbmGuidanceMessageType"
				:result="tbmGuidanceResult"
				@update-field="updateTBMGuidanceForm"
				@submit="callTBMGuidance"
			/>

			<div v-if="activeTab === 'rawTest'" class="raw-test-panel">
				<div class="call-title">WebService 原始请求与连通测试</div>
				<div class="preset-group">
					<span class="preset-label">快捷预设：</span>
					<button type="button" class="preset-btn" @click="applyPreset('getData')">SOAP getData (盾构)</button>
					<button type="button" class="preset-btn" @click="applyPreset('getTBM')">SOAP getTBM (导向)</button>
					<button type="button" class="preset-btn" @click="applyPreset('wsdl')">WSDL 获取 (?wsdl)</button>
					<button type="button" class="preset-btn" @click="applyPreset('ping')">HTTP Ping (GET /)</button>
					<button type="button" class="preset-btn reset" @click="applyPreset('clear')">清空重置</button>
				</div>

				<form class="raw-form" @submit.prevent="sendRawTest">
					<div class="form-row">
						<label class="field-label">请求方法与地址</label>
						<div class="url-input-group">
							<select v-model="rawTestForm.method" class="method-select">
								<option value="POST">POST</option>
								<option value="GET">GET</option>
								<option value="PUT">PUT</option>
								<option value="DELETE">DELETE</option>
								<option value="HEAD">HEAD</option>
							</select>
							<input
								v-model="rawTestForm.url"
								class="url-input"
								type="text"
								placeholder="http://IP:端口/Service.asmx"
								required
							/>
							<div class="timeout-wrap">
								<span>超时(秒):</span>
								<input v-model.number="rawTestForm.timeout" type="number" min="1" max="60" class="timeout-input" />
							</div>
						</div>
					</div>

					<div class="form-row">
						<div class="field-label-group">
							<label class="field-label">请求头 (Headers)</label>
							<span class="field-hint">每行一个，格式为 Name: Value</span>
						</div>
						<textarea
							v-model="rawTestForm.rawHeaders"
							class="code-textarea headers-textarea"
							placeholder="Content-Type: text/xml; charset=utf-8&#10;SOAPAction: &quot;http://tempuri.org/getData&quot;"
							rows="3"
							spellcheck="false"
						></textarea>
					</div>

					<div v-if="rawTestForm.method !== 'GET' && rawTestForm.method !== 'HEAD'" class="form-row">
						<div class="field-label-group">
							<label class="field-label">请求报文 (Request Body / SOAP XML)</label>
							<span class="field-hint">支持 SOAP XML / JSON / 纯文本</span>
						</div>
						<textarea
							v-model="rawTestForm.body"
							class="code-textarea body-textarea"
							placeholder="<?xml version=&quot;1.0&quot; encoding=&quot;utf-8&quot;?>&#10;<soap:Envelope ...>...</soap:Envelope>"
							rows="8"
							spellcheck="false"
						></textarea>
					</div>

					<div class="form-row">
						<div class="field-label-group">
							<label class="field-label">对应 curl 命令行预览</label>
							<button type="button" class="copy-btn" @click="copyText(curlPreview, 'curlTip')">
								{{ curlTip || '复制 curl 命令' }}
							</button>
						</div>
						<pre class="curl-preview"><code>{{ curlPreview }}</code></pre>
					</div>

					<div class="xieyi-actions raw-actions">
						<button type="submit" class="submit-btn" :disabled="rawTestLoading">
							{{ rawTestLoading ? '正在测试连接...' : '发送测试 (Send)' }}
						</button>
						<span v-if="rawTestResult" class="elapsed-tag">
							耗时: {{ rawTestResult.elapsedMs }} ms
						</span>
					</div>
				</form>

				<div v-if="rawTestResult" class="test-result-box">
					<div class="result-header">
						<div class="result-title">响应测试结果</div>
						<div class="result-meta">
							<span class="badge" :class="rawTestResult.success ? 'badge-success' : 'badge-danger'">
								{{ rawTestResult.status || (rawTestResult.statusCode ? 'HTTP ' + rawTestResult.statusCode : '连接失败') }}
							</span>
							<span class="elapsed-meta">往返耗时: {{ rawTestResult.elapsedMs }} ms</span>
							<button type="button" class="copy-btn" @click="copyText(rawTestResult.body || rawTestResult.error || '', 'bodyTip')">
								{{ bodyTip || '复制响应内容' }}
							</button>
						</div>
					</div>

					<div v-if="rawTestResult.error" class="error-banner">
						<strong>连通异常 / 诊断：</strong> {{ rawTestResult.error }}
					</div>

					<div v-if="rawTestResult.headers && Object.keys(rawTestResult.headers).length" class="sub-section">
						<div class="section-subtitle" @click="showHeaders = !showHeaders" style="cursor: pointer;">
							<span>响应头 (Response Headers)</span>
							<span class="toggle-icon">{{ showHeaders ? '▲ 收起' : '▼ 展开' }}</span>
						</div>
						<table v-if="showHeaders" class="headers-table">
							<tbody>
								<tr v-for="(val, key) in rawTestResult.headers" :key="key">
									<td class="header-key">{{ key }}</td>
									<td class="header-val">{{ val }}</td>
								</tr>
							</tbody>
						</table>
					</div>

					<div class="sub-section">
						<div class="section-subtitle">响应报文内容 (Response Body)</div>
						<pre class="response-body"><code>{{ rawTestResult.body || (rawTestResult.error ? '无响应报文 (远程服务未能连通)' : '(空响应体)') }}</code></pre>
					</div>
				</div>
			</div>
		</div>
	</div>
</template>

<script setup>
import { computed, defineComponent, h, onMounted, ref } from 'vue'

const tabs = [
	{ key: 'protocols', label: '协议说明' },
	{ key: 'callData', label: '盾构数据调用' },
	{ key: 'callGuidance', label: '导向数据调用' },
	{ key: 'rawTest', label: '连通测试' }
]

const activeTab = ref('protocols')
const loading = ref(false)
const protocols = ref([])
const message = ref('')
const messageType = ref('info')
const defaultServiceUrl = 'http://127.0.0.1/Service.asmx'

const tbmDataForm = ref({
	serviceUrl: defaultServiceUrl,
	flag: 'tbmData',
	mac: '',
	psw: ''
})
const tbmGuidanceForm = ref({
	serviceUrl: defaultServiceUrl,
	mac: '',
	psw: ''
})
const tbmDataCalling = ref(false)
const tbmGuidanceCalling = ref(false)
const tbmDataMessage = ref('')
const tbmGuidanceMessage = ref('')
const tbmDataMessageType = ref('info')
const tbmGuidanceMessageType = ref('info')
const tbmDataResult = ref(null)
const tbmGuidanceResult = ref(null)

const setMessage = (text, type = 'info') => {
	message.value = text
	messageType.value = type
}

const fetchJSON = async (url, options) => {
	const response = await fetch(url, options)
	const text = await response.text()
	let payload = null
	if (text) {
		try {
			payload = JSON.parse(text)
		} catch {
			throw new Error(text)
		}
	}
	if (!response.ok) {
		throw new Error(text || `Request failed: ${response.status}`)
	}
	return payload
}

const fetchProtocol = (url) => fetchJSON(url)

const loadProtocols = async () => {
	loading.value = true
	setMessage('Reading protocol data ...')

	try {
		const data = await Promise.all([
			fetchProtocol('/api/xieyi/tbm-data'),
			fetchProtocol('/api/xieyi/tbm-guidance')
		])
		protocols.value = data
		setMessage('Read success.')
	} catch (err) {
		setMessage(err instanceof Error ? err.message : 'Read failed.', 'error')
	} finally {
		loading.value = false
	}
}

const postCall = (url, payload) => fetchJSON(url, {
	method: 'POST',
	headers: {
		'Content-Type': 'application/json'
	},
	body: JSON.stringify(payload)
})

const updateTBMDataForm = (key, value) => {
	tbmDataForm.value = {
		...tbmDataForm.value,
		[key]: value
	}
}

const updateTBMGuidanceForm = (key, value) => {
	tbmGuidanceForm.value = {
		...tbmGuidanceForm.value,
		[key]: value
	}
}

const callTBMData = async () => {
	tbmDataCalling.value = true
	tbmDataMessage.value = 'Sending ...'
	tbmDataMessageType.value = 'info'

	try {
		tbmDataResult.value = await postCall('/api/xieyi/call-tbm-data', tbmDataForm.value)
		tbmDataMessage.value = 'Send success.'
	} catch (err) {
		tbmDataMessage.value = err instanceof Error ? err.message : 'Send failed.'
		tbmDataMessageType.value = 'error'
	} finally {
		tbmDataCalling.value = false
	}
}

const callTBMGuidance = async () => {
	tbmGuidanceCalling.value = true
	tbmGuidanceMessage.value = 'Sending ...'
	tbmGuidanceMessageType.value = 'info'

	try {
		tbmGuidanceResult.value = await postCall('/api/xieyi/call-tbm-guidance', tbmGuidanceForm.value)
		tbmGuidanceMessage.value = 'Send success.'
	} catch (err) {
		tbmGuidanceMessage.value = err instanceof Error ? err.message : 'Send failed.'
		tbmGuidanceMessageType.value = 'error'
	} finally {
		tbmGuidanceCalling.value = false
	}
}

const rawTestForm = ref({
	url: defaultServiceUrl,
	method: 'POST',
	timeout: 10,
	rawHeaders: 'Content-Type: text/xml; charset=utf-8\nSOAPAction: "http://tempuri.org/getData"',
	body: `<?xml version="1.0" encoding="utf-8"?>
<soap:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/">
  <soap:Body>
    <getData xmlns="http://tempuri.org/">
      <flag>tbmData</flag>
      <mac>DL898</mac>
      <psw>123456</psw>
    </getData>
  </soap:Body>
</soap:Envelope>`
})

const rawTestLoading = ref(false)
const rawTestResult = ref(null)
const showHeaders = ref(false)
const curlTip = ref('')
const bodyTip = ref('')

const curlPreview = computed(() => {
	let cmd = `curl -X ${rawTestForm.value.method || 'POST'} "${rawTestForm.value.url || ''}"`
	if (rawTestForm.value.rawHeaders) {
		const lines = rawTestForm.value.rawHeaders.split('\n')
		for (const line of lines) {
			const trimmed = line.trim()
			if (trimmed && !trimmed.startsWith('#') && !trimmed.startsWith('//')) {
				cmd += ` \\\n  -H "${trimmed.replace(/"/g, '\\"')}"`
			}
		}
	}
	if (rawTestForm.value.body && rawTestForm.value.method !== 'GET' && rawTestForm.value.method !== 'HEAD') {
		const oneLine = rawTestForm.value.body.replace(/\r?\n/g, '').replace(/"/g, '\\"')
		cmd += ` \\\n  -d "${oneLine}"`
	}
	return cmd
})

const applyPreset = (type) => {
	switch (type) {
		case 'getData':
			rawTestForm.value = {
				url: rawTestForm.value.url || defaultServiceUrl,
				method: 'POST',
				timeout: 10,
				rawHeaders: 'Content-Type: text/xml; charset=utf-8\nSOAPAction: "http://tempuri.org/getData"',
				body: `<?xml version="1.0" encoding="utf-8"?>
<soap:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/">
  <soap:Body>
    <getData xmlns="http://tempuri.org/">
      <flag>tbmData</flag>
      <mac>DL898</mac>
      <psw>123456</psw>
    </getData>
  </soap:Body>
</soap:Envelope>`
			}
			break
		case 'getTBM':
			rawTestForm.value = {
				url: rawTestForm.value.url || defaultServiceUrl,
				method: 'POST',
				timeout: 10,
				rawHeaders: 'Content-Type: text/xml; charset=utf-8\nSOAPAction: "http://tempuri.org/getTBM"',
				body: `<?xml version="1.0" encoding="utf-8"?>
<soap:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/">
  <soap:Body>
    <getTBM xmlns="http://tempuri.org/">
      <mac>DL898</mac>
      <psw>123456</psw>
    </getTBM>
  </soap:Body>
</soap:Envelope>`
			}
			break
		case 'wsdl':
			rawTestForm.value = {
				url: (rawTestForm.value.url ? rawTestForm.value.url.split('?')[0] : defaultServiceUrl) + '?wsdl',
				method: 'GET',
				timeout: 10,
				rawHeaders: '',
				body: ''
			}
			break
		case 'ping':
			rawTestForm.value = {
				url: 'http://127.0.0.1/',
				method: 'GET',
				timeout: 5,
				rawHeaders: '',
				body: ''
			}
			break
		case 'clear':
			rawTestForm.value = {
				url: '',
				method: 'POST',
				timeout: 10,
				rawHeaders: '',
				body: ''
			}
			rawTestResult.value = null
			break
	}
}

const sendRawTest = async () => {
	rawTestLoading.value = true
	rawTestResult.value = null
	try {
		const res = await postCall('/api/xieyi/raw-test', {
			url: rawTestForm.value.url,
			method: rawTestForm.value.method,
			timeout: Number(rawTestForm.value.timeout) || 10,
			rawHeaders: rawTestForm.value.rawHeaders,
			body: rawTestForm.value.body
		})
		rawTestResult.value = res
	} catch (err) {
		rawTestResult.value = {
			success: false,
			statusCode: 0,
			status: 'Request Failed',
			elapsedMs: 0,
			error: err instanceof Error ? err.message : String(err)
		}
	} finally {
		rawTestLoading.value = false
	}
}

const copyText = async (text, tipRefName) => {
	if (!text) return
	try {
		await navigator.clipboard.writeText(text)
		if (tipRefName === 'curlTip') {
			curlTip.value = '已复制！'
			setTimeout(() => { curlTip.value = '' }, 2000)
		} else if (tipRefName === 'bodyTip') {
			bodyTip.value = '已复制！'
			setTimeout(() => { bodyTip.value = '' }, 2000)
		}
	} catch {
		const ta = document.createElement('textarea')
		ta.value = text
		document.body.appendChild(ta)
		ta.select()
		document.execCommand('copy')
		document.body.removeChild(ta)
		if (tipRefName === 'curlTip') {
			curlTip.value = '已复制！'
			setTimeout(() => { curlTip.value = '' }, 2000)
		} else if (tipRefName === 'bodyTip') {
			bodyTip.value = '已复制！'
			setTimeout(() => { bodyTip.value = '' }, 2000)
		}
	}
}

const CallPanel = defineComponent({
	props: {
		title: String,
		showFlag: Boolean,
		form: Object,
		loading: Boolean,
		message: String,
		messageType: String,
		result: Object
	},
	emits: ['submit', 'update-field'],
	setup(props, { emit }) {
		return () => h('form', {
			class: 'call-panel',
			onSubmit: (event) => {
				event.preventDefault()
				emit('submit')
			}
		}, [
			h('div', { class: 'call-title' }, props.title),
			h('label', ['Service.asmx 地址', h('input', {
				value: props.form.serviceUrl,
				onInput: (event) => { emit('update-field', 'serviceUrl', event.target.value) },
				placeholder: 'http://IP:Port/Service.asmx'
			})]),
			props.showFlag ? h('label', ['flag', h('input', {
				value: props.form.flag,
				onInput: (event) => { emit('update-field', 'flag', event.target.value) },
				placeholder: 'tbmData'
			})]) : null,
			h('label', ['mac', h('input', {
				value: props.form.mac,
				onInput: (event) => { emit('update-field', 'mac', event.target.value) },
				placeholder: '设备编号，如 DL898'
			})]),
			h('label', ['psw', h('input', {
				value: props.form.psw,
				onInput: (event) => { emit('update-field', 'psw', event.target.value) },
				placeholder: '接口调用密钥'
			})]),
			h('div', { class: 'xieyi-actions' }, [
				h('button', { type: 'submit', disabled: props.loading }, '发送'),
				h('span', { class: ['xieyi-message', { error: props.messageType === 'error' }] }, props.message)
			]),
			props.result ? h('div', [
				h('div', { class: 'table-title' }, '返回数据'),
				h('table', [
					h('thead', h('tr', [
						h('th', '序号'),
						h('th', '名称'),
						h('th', '值'),
						h('th', '单位')
					])),
					h('tbody', props.result.values.map((item) => h('tr', { key: item.index }, [
						h('td', item.index),
						h('td', item.name),
						h('td', item.value),
						h('td', item.unit || '-')
					])))
				])
			]) : null
		])
	}
})

onMounted(() => {
	loadProtocols()
})
</script>

<style scoped lang="less">
.xieyi-page {
	height: 100vh;
	overflow-y: auto;
	padding: 48px 16px;
	background: #fff;
	color: #222;
	box-sizing: border-box;
	font-family: "Microsoft YaHei", "微软雅黑", sans-serif;
	font-weight: normal;
}

.xieyi-page * {
	font-family: "Microsoft YaHei", "微软雅黑", sans-serif;
	font-weight: normal;
}

.xieyi-form {
	width: 960px;
	max-width: 100%;
	margin: 0 auto;
}

.tabs {
	display: flex;
	gap: 6px;
	margin-bottom: 16px;
	border-bottom: 1px solid #999;
}

.tabs button {
	padding: 6px 14px;
	border: 1px solid #999;
	border-bottom: 0;
	background: #fff;
	color: #000;
	font-family: inherit;
	cursor: pointer;
}

.xieyi-page .tabs button.active,
.xieyi-page .tabs button:hover,
.xieyi-page .tabs button:focus {
	color: #000;
}

.xieyi-page .tabs button.active {
	font-weight: bold;
}

.xieyi-actions {
	display: flex;
	align-items: center;
	gap: 8px;
	margin-bottom: 16px;
}

.xieyi-actions button {
	padding: 4px 12px;
	font-family: inherit;
}

.xieyi-message {
	color: #333;
	font-size: 14px;
}

.xieyi-message.error {
	color: #c00;
}

.protocol-section {
	margin-bottom: 28px;
	padding-bottom: 20px;
	border-bottom: 1px solid #ddd;
}

.field-row {
	display: grid;
	grid-template-columns: 88px 1fr;
	gap: 12px;
	margin-bottom: 8px;
	font-size: 14px;
}

.field-row label {
	color: #555;
}

:deep(.call-panel) {
	display: grid;
	gap: 12px;
	width: 1100px;
}

:deep(.call-panel label) {
	display: grid;
	grid-template-columns: 220px 820px;
	align-items: center;
	gap: 12px;
	font-size: 14px;
}

:deep(.call-panel input) {
	width: 820px;
	padding: 6px 8px;
	border: 1px solid #999;
	font-family: inherit;
	font-size: 14px;
	box-sizing: border-box;
}

.table-title {
	margin: 14px 0 8px;
	font-size: 14px;
}

table {
	width: 100%;
